def binary_search(arr, target):
    """
    Search for target in a sorted array.
    Returns index if found, else -1.
    """
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = low + (high - low) // 2  # avoids integer overflow in some languages

        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1


def linear_search(arr, target):
    """
    Scan array element-by-element.
    Returns index if found, else -1.
    """
    for i, value in enumerate(arr):
        if value == target:
            return i
    return -1

