"""
data_pipeline.py

A modular pipeline: Ingest -> Clean -> Aggregate -> Report
"""

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Callable, Iterable
from collections import defaultdict
import csv
import io
import math
import statistics
import logging

logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
logger = logging.getLogger("pipeline")


# ---------------------------------------------------------------------------
# 1. Schema / Type Definitions
# ---------------------------------------------------------------------------

@dataclass
class Field:
    """Describes a single column: how to parse it and how to fill gaps."""
    name: str
    dtype: str                      # "int", "float", "str", "category"
    required: bool = False          # drop row if missing & required
    default: Any = None             # fill value when missing (if not required)
    parser: Callable[[str], Any] | None = None

    def cast(self, raw: str) -> Any:
        raw = (raw or "").strip()
        if raw in ("", "NA", "N/A", "null", "NaN", "-"):
            raise ValueError("missing")
        if self.parser:
            return self.parser(raw)
        if self.dtype == "int":
            return int(float(raw))          # tolerate "10.0"
        if self.dtype == "float":
            v = float(raw)
            if math.isnan(v) or math.isinf(v):
                raise ValueError("non-finite")
            return v
        return raw                          # str / category


@dataclass
class Schema:
    fields: list[Field]

    @property
    def by_name(self) -> dict[str, Field]:
        return {f.name: f for f in self.fields}


# ---------------------------------------------------------------------------
# 2. Ingestion
# ---------------------------------------------------------------------------

def ingest_csv(source: str | io.TextIOBase) -> Iterable[dict[str, str]]:
    """Yield raw rows as dicts. Accepts a file path or a text stream."""
    if isinstance(source, str):
        with open(source, newline="", encoding="utf-8") as fh:
            yield from csv.DictReader(fh)
    else:
        yield from csv.DictReader(source)


# ---------------------------------------------------------------------------
# 3. Cleaning
# ---------------------------------------------------------------------------

@dataclass
class CleaningStats:
    total: int = 0
    kept: int = 0
    dropped: int = 0
    imputed: dict[str, int] = field(default_factory=lambda: defaultdict(int))
    malformed: dict[str, int] = field(default_factory=lambda: defaultdict(int))

    def report(self) -> str:
        lines = [
            f"Rows read:    {self.total}",
            f"Rows kept:    {self.kept}",
            f"Rows dropped: {self.dropped}",
        ]
        if self.imputed:
            lines.append("Imputed (filled) values:")
            lines += [f"  {k}: {v}" for k, v in self.imputed.items()]
        if self.malformed:
            lines.append("Malformed values encountered:")
            lines += [f"  {k}: {v}" for k, v in self.malformed.items()]
        return "\n".join(lines)


def clean(rows: Iterable[dict[str, str]], schema: Schema) -> tuple[list[dict], CleaningStats]:
    """
    Parse & validate each row per the schema.

    - Malformed/missing required fields  -> drop the row.
    - Malformed/missing optional fields  -> impute with `default`.
    """
    stats = CleaningStats()
    cleaned: list[dict] = []

    for raw in rows:
        stats.total += 1
        record: dict[str, Any] = {}
        drop = False

        for f in schema.fields:
            value = raw.get(f.name)
            try:
                record[f.name] = f.cast(value)
            except (ValueError, TypeError):
                stats.malformed[f.name] += 1
                if f.required:
                    drop = True
                    break
                record[f.name] = f.default
                stats.imputed[f.name] += 1

        if drop:
            stats.dropped += 1
        else:
            cleaned

