import time
import functools
from collections import OrderedDict


def expensive_computation(n):
    """Simulates a costly operation (e.g., DB query, API call, heavy math)."""
    time.sleep(0.5)  # Simulate latency
    return n * n


# --- Approach 1: Simple unbounded cache (dict) ---
class SimpleCache:
    def __init__(self, func):
        self.func = func
        self.store = {}

    def __call__(self, *args):
        if args in self.store:
            return self.store[args]        # Cache hit
        result = self.func(*args)          # Cache miss -> compute
        self.store[args] = result
        return result


# --- Approach 2: Bounded cache with LRU eviction ---
class LRUCache:
    def __init__(self, func, capacity=128):
        self.func = func
        self.capacity = capacity
        self.store = OrderedDict()
        self.hits = 0
        self.misses = 0

    def __call__(self, *args):
        if args in self.store:
            self.store.move_to_end(args)   # Mark as recently used
            self.hits += 1
            return self.store[args]

        self.misses += 1
        result = self.func(*args)
        self.store[args] = result

        if len(self.store) > self.capacity:
            self.store.popitem(last=False)  # Evict least recently used
        return result

    def stats(self):
        return {"hits": self.hits, "misses": self.misses,
                "size": len(self.store)}


# --- Approach 3: Built-in (production choice) ---
@functools.lru_cache(maxsize=128)
def cached_computation(n):
    time.sleep(0.5)
    return n * n
